INSERT INTO "vulnerabilities" VALUES('GHSA-9hjg-9r4m-mvj7','["CVE-2024-47081","PYSEC-2026-1872"]','Requests vulnerable to .netrc credentials leak via malicious URLs','### Impact

Due to a URL parsing issue, Requests releases prior to 2.32.4 may leak .netrc credentials to third parties for specific maliciously-crafted URLs.

### Workarounds
For older versions of Requests, use of the .netrc file can be disabled with `trust_env=False` on your Requests Session ([docs','MEDIUM','2025-06-09T19:06:08Z','2026-10-19T20:00:04.716114530Z','["https://github.com/psf/requests/security/advisories/GHSA-9hjg-9r4m-mvj7","https://nvd.nist.gov/vuln/detail/CVE-2024-47081","https://github.com/psf/requests/pull/6965","https://github.com/psf/requests/commit/96ba401c1296ab1dda74a2365ef36d88f7d144ef","https://github.com/advisories/GHSA-9hjg-9r4m-mvj7","https://github.com/psf/requests","https://github.com/psf/requests/releases/tag/v2.32.4","https://github.com/pypa/advisory-database/tree/main/vulns/requests/PYSEC-2026-1872.yaml","https://pypi.org/project/requests","https://requests.readthedocs.io/en/latest/api/#requests.Session.trust_env","https://seclists.org/fulldisclosure/2025/Jun/2","http://www.openwall.com/lists/oss-security/2025/06/03/11","http://www.openwall.com/lists/oss-security/2025/06/03/9","http://www.openwall.com/lists/oss-security/2025/06/04/1","http://www.openwall.com/lists/oss-security/2025/06/04/6"]','{}','2026-10-28T07:37:43Z',0,'',0.0098,5.3);
INSERT INTO "vulnerabilities" VALUES('GHSA-9wx4-h78v-vm56','["CVE-2024-35195","PYSEC-2026-1873"]','Requests `Session` object does not verify requests after making first request with verify=False','When using a `requests.Session`, if the first request to a given origin is made with `verify=False`, TLS certificate verification may remain disabled for all subsequent requests to that origin, even if `verify=True` is explicitly specified later.

This occurs because the underlying connection is reu','MEDIUM','2024-05-20T20:15:00Z','2026-09-10T03:50:13.740879755Z','["https://github.com/psf/requests/security/advisories/GHSA-9wx4-h78v-vm56","https://nvd.nist.gov/vuln/detail/CVE-2024-35195","https://github.com/psf/requests/pull/6655","https://github.com/psf/requests/commit/a58d7f2ffb4d00b46dca2d70a3932a0b37e22fac","https://github.com/psf/requests","https://lists.fedoraproject.org/archives/list/package-announce@lists.fedoraproject.org/message/IYLSNK5TL46Q6XPRVMHVWS63MVJQOK4Q","https://lists.fedoraproject.org/archives/list/package-announce@lists.fedoraproject.org/message/N7WP6EYDSUOCOJYHDK5NX43PYZ4SNHGZ"]','{}','2026-10-28T07:37:43Z',0,'',0.0034,5.6);
INSERT INTO "vulnerabilities" VALUES('GHSA-gc5v-m9x4-r6x2','["CVE-2026-25645","PYSEC-2026-2275"]','Requests has Insecure Temp File Reuse in its extract_zipped_paths() utility function','### Impact
The `requests.utils.extract_zipped_paths()` utility function uses a predictable filename when extracting files from zip archives into the system temporary directory. If the target file already exists, it is reused without validation. A local attacker with write access to the temp director','MEDIUM','2026-03-25T16:56:28Z','2026-09-10T03:50:39.207922076Z','["https://github.com/psf/requests/security/advisories/GHSA-gc5v-m9x4-r6x2","https://nvd.nist.gov/vuln/detail/CVE-2026-25645","https://github.com/psf/requests/commit/66d21cb07bd6255b1280291c4fafb71803cdb3b7","https://github.com/psf/requests","https://github.com/psf/requests/releases/tag/v2.33.0"]','{}','2026-10-28T07:37:44Z',0,'',0.00189,4.4);
INSERT INTO "vulnerabilities" VALUES('GHSA-j8r2-6x86-q33q','["CVE-2023-32681","PYSEC-2023-74"]','Unintended leak of Proxy-Authorization header in requests','### Impact

Since Requests v2.3.0, Requests has been vulnerable to potentially leaking `Proxy-Authorization` headers to destination servers, specifically during redirects to an HTTPS origin. This is a product of how `rebuild_proxies` is used to recompute and [reattach the `Proxy-Authorization` heade','MEDIUM','2023-05-22T20:36:32Z','2026-09-10T03:50:01.756149727Z','["https://github.com/psf/requests/security/advisories/GHSA-j8r2-6x86-q33q","https://nvd.nist.gov/vuln/detail/CVE-2023-32681","https://github.com/psf/requests/commit/74ea7cf7a6a27a4eeb2ae24e162bcc942a6706d5","https://github.com/psf/requests","https://github.com/psf/requests/releases/tag/v2.31.0","https://github.com/pypa/advisory-database/tree/main/vulns/requests/PYSEC-2023-74.yaml","https://lists.debian.org/debian-lts-announce/2023/06/msg00018.html","https://lists.fedoraproject.org/archives/list/package-announce@lists.fedoraproject.org/message/AW7HNFGYP44RT3DUDQXG2QT3OEV2PJ7Y","https://lists.fedoraproject.org/archives/list/package-announce@lists.fedoraproject.org/message/KOYASTZDGQG2BWLSNBPL3TQRL2G7QYNZ","https://security.gentoo.org/glsa/202309-08"]','{}','2026-10-28T07:37:44Z',0,'',0.02974,6.1);
INSERT INTO "vulnerabilities" VALUES('GHSA-x84v-xcm2-53pg','["CVE-2018-18074","PYSEC-2018-28"]','Insufficiently Protected Credentials in Requests','The Requests package through 2.19.1 before 2018-09-14 for Python sends an HTTP Authorization header to an http URI upon receiving a same-hostname https-to-http redirect, which makes it easier for remote attackers to discover credentials by sniffing the network.','HIGH','2018-10-29T19:06:46Z','2024-10-21T21:42:55.896669Z','["https://nvd.nist.gov/vuln/detail/CVE-2018-18074","https://github.com/requests/requests/issues/4716","https://github.com/requests/requests/pull/4718","https://github.com/requests/requests/commit/c45d7c49ea75133e52ab22a8e9e13173938e36ff","https://access.redhat.com/errata/RHSA-2019:2035","https://bugs.debian.org/910766","https://github.com/pypa/advisory-database/tree/main/vulns/requests/PYSEC-2018-28.yaml","https://github.com/requests/requests","https://usn.ubuntu.com/3790-1","https://usn.ubuntu.com/3790-2","https://www.oracle.com/security-alerts/cpujul2022.html","http://docs.python-requests.org/en/master/community/updates/#release-and-version-history","http://lists.opensuse.org/opensuse-security-announce/2019-07/msg00024.html"]','{}','2026-10-28T07:37:44Z',0,'',0.06925,7.5);
INSERT INTO "vulnerabilities" VALUES('PYSEC-2018-28','["CVE-2018-18074","GHSA-x84v-xcm2-53pg"]','','The Requests package before 2.20.0 for Python sends an HTTP Authorization header to an http URI upon receiving a same-hostname https-to-http redirect, which makes it easier for remote attackers to discover credentials by sniffing the network.','','2018-10-09T17:29:00Z','2023-11-08T04:00:04.815794Z','["https://github.com/requests/requests/pull/4718","https://github.com/requests/requests/issues/4716","https://github.com/requests/requests/commit/c45d7c49ea75133e52ab22a8e9e13173938e36ff","https://bugs.debian.org/910766","https://usn.ubuntu.com/3790-1/","http://docs.python-requests.org/en/master/community/updates/#release-and-version-history","https://usn.ubuntu.com/3790-2/","http://lists.opensuse.org/opensuse-security-announce/2019-07/msg00024.html","https://access.redhat.com/errata/RHSA-2019:2035","https://github.com/advisories/GHSA-x84v-xcm2-53pg"]','{}','2026-10-28T07:37:44Z',0,'',0.06925,-1.0);
INSERT INTO "vulnerabilities" VALUES('GHSA-462w-v97r-4m45','["CVE-2019-10906","PYSEC-2019-217"]','Jinja2 sandbox escape via string formatting','In Pallets Jinja before 2.10.1, `str.format_map` allows a sandbox escape.

The sandbox is used to restrict what code can be evaluated when rendering untrusted, user-provided templates. Due to the way string formatting works in Python, the `str.format_map` method could be used to escape the sandbox.
','HIGH','2019-04-10T14:30:24Z','2024-09-24T21:03:59.802687Z','["https://nvd.nist.gov/vuln/detail/CVE-2019-10906","https://usn.ubuntu.com/4011-2","https://usn.ubuntu.com/4011-1","https://palletsprojects.com/blog/jinja-2-10-1-released","https://lists.fedoraproject.org/archives/list/package-announce@lists.fedoraproject.org/message/TS7IVZAJBWOHNRDMFJDIZVFCMRP6YIUQ","https://lists.fedoraproject.org/archives/list/package-announce@lists.fedoraproject.org/message/QCDYIS254EJMBNWOG4S5QY6AOTOR4TZU","https://lists.fedoraproject.org/archives/list/package-announce@lists.fedoraproject.org/message/DSW3QZMFVVR7YE3UT4YRQA272TYAL5AF","https://lists.apache.org/thread.html/f0c4a03418bcfe70c539c5dbaf99c04c98da13bfa1d3266f08564316@%3Ccommits.airflow.apache.org%3E","https://lists.apache.org/thread.html/b2380d147b508bbcb90d2cad443c159e63e12555966ab4f320ee22da@%3Ccommits.airflow.apache.org%3E","https://lists.apache.org/thread.html/7f39f01392d320dfb48e4901db68daeece62fd60ef20955966739993@%3Ccommits.airflow.apache.org%3E","https://lists.apache.org/thread.html/57673a78c4d5c870d3f21465c7e2946b9f8285c7c57e54c2ae552f02@%3Ccommits.airflow.apache.org%3E","https://lists.apache.org/thread.html/46c055e173b52d599c648a98199972dbd6a89d2b4c4647b0500f2284@%3Cdevnull.infra.apache.org%3E","https://lists.apache.org/thread.html/320441dccbd9a545320f5f07306d711d4bbd31ba43dc9eebcfc602df@%3Cdevnull.infra.apache.org%3E","https://lists.apache.org/thread.html/2b52b9c8b9d6366a4f1b407a8bde6af28d9fc73fdb3b37695fd0d9ac@%3Cdevnull.infra.apache.org%3E","https://lists.apache.org/thread.html/09fc842ff444cd43d9d4c510756fec625ef8eb1175f14fd21de2605f@%3Cdevnull.infra.apache.org%3E","https://github.com/pypa/advisory-database/tree/main/vulns/jinja2/PYSEC-2019-217.yaml","https://github.com/pallets/jinja","https://github.com/advisories/GHSA-462w-v97r-4m45","https://access.redhat.com/errata/RHSA-2019:1329","https://access.redhat.com/errata/RHSA-2019:1237","https://access.redhat.com/errata/RHSA-2019:1152","http://lists.opensuse.org/opensuse-security-announce/2019-05/msg00030.html","http://lists.opensuse.org/opensuse-security-announce/2019-06/msg00064.html"]','{}','2026-10-28T07:37:45Z',0,'',0.03534,8.6);
INSERT INTO "vulnerabilities" VALUES('GHSA-cpwx-vrp4-4pq7','["CVE-2025-27516","PYSEC-2026-1471"]','Jinja2 vulnerable to sandbox breakout through attr filter selecting format method','An oversight in how the Jinja sandboxed environment interacts with the `|attr` filter allows an attacker that controls the content of a template to execute arbitrary Python code.

To exploit the vulnerability, an attacker needs to control the content of a template. Whether that is the case depends o','MEDIUM','2025-03-05T20:40:14Z','2026-09-10T03:49:48.526758681Z','["https://github.com/pallets/jinja/security/advisories/GHSA-cpwx-vrp4-4pq7","https://nvd.nist.gov/vuln/detail/CVE-2025-27516","https://github.com/pallets/jinja/commit/90457bbf33b8662926ae65cdde4c4c32e756e403","https://github.com/pallets/jinja","https://lists.debian.org/debian-lts-announce/2025/04/msg00022.html","https://lists.debian.org/debian-lts-announce/2025/04/msg00045.html"]','{}','2026-10-28T07:37:45Z',0,'',0.00507,-1.0);
INSERT INTO "vulnerabilities" VALUES('GHSA-g3rq-g295-4j3m','["CVE-2020-28493","PYSEC-2021-66","SNYK-PYTHON-JINJA2-1012994"]','Regular Expression Denial of Service (ReDoS) in Jinja2','This affects the package jinja2 from 0.0.0 and before 2.11.3. The ReDOS vulnerability of the regex is mainly due to the sub-pattern [a-zA-Z0-9._-]+.[a-zA-Z0-9._-]+ This issue can be mitigated by Markdown to format user content instead of the urlize filter, or by implementing request timeouts and lim','MEDIUM','2021-03-19T21:28:05Z','2025-02-14T05:26:14.565160Z','["https://nvd.nist.gov/vuln/detail/CVE-2020-28493","https://github.com/pallets/jinja/pull/1343","https://github.com/pallets/jinja/commit/15ef8f09b659f9100610583938005a7a10472d4d","https://github.com/advisories/GHSA-g3rq-g295-4j3m","https://github.com/pallets/jinja","https://github.com/pallets/jinja/blob/ab81fd9c277900c85da0c322a2ff9d68a235b2e6/src/jinja2/utils.py%23L20","https://github.com/pypa/advisory-database/tree/main/vulns/jinja2/PYSEC-2021-66.yaml","https://lists.fedoraproject.org/archives/list/package-announce@lists.fedoraproject.org/message/PVAKCOO7VBVUBM3Q6CBBTPBFNP5NDXF4","https://security.gentoo.org/glsa/202107-19","https://snyk.io/vuln/SNYK-PYTHON-JINJA2-1012994"]','{}','2026-10-28T07:37:46Z',0,'',0.03589,5.3);
INSERT INTO "vulnerabilities" VALUES('GHSA-h5c8-rqwp-cp95','["CVE-2024-22195","PYSEC-2026-1473"]','Jinja vulnerable to HTML attribute injection when passing user input as keys to xmlattr filter','The `xmlattr` filter in affected versions of Jinja accepts keys containing spaces. XML/HTML attributes cannot contain spaces, as each would then be interpreted as a separate attribute. If an application accepts keys (as opposed to only values) as user input, and renders these in pages that other use','MEDIUM','2024-01-11T15:20:48Z','2026-09-10T03:50:00.236017440Z','["https://github.com/pallets/jinja/security/advisories/GHSA-h5c8-rqwp-cp95","https://nvd.nist.gov/vuln/detail/CVE-2024-22195","https://github.com/pallets/jinja/commit/716795349a41d4983a9a4771f7d883c96ea17be7","https://github.com/pallets/jinja","https://github.com/pallets/jinja/releases/tag/3.1.3","https://lists.debian.org/debian-lts-announce/2024/01/msg00010.html","https://lists.debian.org/debian-lts-announce/2024/12/msg00009.html","https://lists.fedoraproject.org/archives/list/package-announce@lists.fedoraproject.org/message/5XCWZD464AJJJUBOO7CMPXQ4ROBC6JX2","https://lists.fedoraproject.org/archives/list/package-announce@lists.fedoraproject.org/message/DELCVUUYX75I5K4Q5WMJG4MUZJA6VAIP","https://lists.fedoraproject.org/archives/list/package-announce@lists.fedoraproject.org/message/O7YWRBX6JQCWC2XXCTZ55C7DPMGICCN3"]','{}','2026-10-28T07:37:46Z',0,'',0.00892,5.4);
INSERT INTO "vulnerabilities" VALUES('GHSA-h75v-3vvj-5mfj','["CVE-2024-34064","PYSEC-2026-1474"]','Jinja vulnerable to HTML attribute injection when passing user input as keys to xmlattr filter','The `xmlattr` filter in affected versions of Jinja accepts keys containing non-attribute characters. XML/HTML attributes cannot contain spaces, `/`, `>`, or `=`, as each would then be interpreted as starting a separate attribute. If an application accepts keys (as opposed to only values) as user inp','MEDIUM','2024-05-06T14:20:59Z','2026-09-10T03:50:13.786450101Z','["https://github.com/pallets/jinja/security/advisories/GHSA-h75v-3vvj-5mfj","https://nvd.nist.gov/vuln/detail/CVE-2024-34064","https://github.com/pallets/jinja/commit/0668239dc6b44ef38e7a6c9f91f312fd4ca581cb","https://github.com/pallets/jinja","https://lists.debian.org/debian-lts-announce/2024/12/msg00009.html","https://lists.fedoraproject.org/archives/list/package-announce@lists.fedoraproject.org/message/567XIGSZMABG6TSMYWD7MIYNJSUQQRUC","https://lists.fedoraproject.org/archives/list/package-announce@lists.fedoraproject.org/message/GCLF44KY43BSVMTE6S53B4V5WP3FRRSE","https://lists.fedoraproject.org/archives/list/package-announce@lists.fedoraproject.org/message/SSCBHIL6BYKR5NRCBXP4XMP2CEEKGFVS","https://lists.fedoraproject.org/archives/list/package-announce@lists.fedoraproject.org/message/ZALNWE3TXPPHVPSI3AZ5CTMSTAVN5UMS"]','{}','2026-10-28T07:37:47Z',0,'',0.00979,5.4);
INSERT INTO "vulnerabilities" VALUES('GHSA-q2x7-8rv6-6q7h','["CVE-2024-56326","PYSEC-2026-1475"]','Jinja has a sandbox breakout through indirect reference to format method','An oversight in how the Jinja sandboxed environment detects calls to `str.format` allows an attacker that controls the content of a template to execute arbitrary Python code.

To exploit the vulnerability, an attacker needs to control the content of a template. Whether that is the case depends on th','MEDIUM','2024-12-23T17:56:08Z','2026-09-10T03:50:21.662855250Z','["https://github.com/pallets/jinja/security/advisories/GHSA-q2x7-8rv6-6q7h","https://nvd.nist.gov/vuln/detail/CVE-2024-56326","https://github.com/pallets/jinja/commit/48b0687e05a5466a91cd5812d604fa37ad0943b4","https://github.com/pallets/jinja","https://github.com/pallets/jinja/releases/tag/3.1.5","https://lists.debian.org/debian-lts-announce/2025/04/msg00022.html"]','{}','2026-10-28T07:37:47Z',0,'',0.00522,7.8);
INSERT INTO "vulnerabilities" VALUES('GHSA-29mw-wpgm-hmr9','["CVE-2020-28500"]','Regular Expression Denial of Service (ReDoS) in lodash','All versions of package lodash prior to 4.17.21 are vulnerable to Regular Expression Denial of Service (ReDoS) via the `toNumber`, `trim` and `trimEnd` functions. 

Steps to reproduce (provided by reporter Liyuan Chen):
```js
var lo = require(''lodash'');

