INSERT INTO "vulnerabilities" VALUES('GHSA-h383-gmxw-35v2','["CVE-2026-34479"]','Apache Log4j 1 to Log4j 2 bridge: silent log event loss in Log4j1XmlLayout due to unescaped XML 1.0 forbidden characters','The `Log4j1XmlLayout` from the Apache Log4j 1-to-Log4j 2 bridge fails to escape characters forbidden by the XML 1.0 standard, producing malformed XML output. Conforming XML parsers are required to reject documents containing such characters with a fatal error, which may cause downstream log processi','MEDIUM','2026-04-10T18:31:18Z','2026-10-26T15:30:05.719203570Z','["https://nvd.nist.gov/vuln/detail/CVE-2026-34479","https://github.com/apache/logging-log4j2/pull/4078","https://github.com/apache/logging-log4j2","https://lists.apache.org/thread/gd0hp6mj17rn3kj279vgy4p7kd4zz5on","https://logging.apache.org/cyclonedx/vdr.xml","https://logging.apache.org/log4j/2.x/migrate-from-log4j1.html","https://logging.apache.org/security.html#CVE-2026-34479","http://www.openwall.com/lists/oss-security/2026/04/10/8"]','{}','2026-10-28T07:37:51Z',0,'',0.00535,-1.0);
